INSERT INTO records (id, collection, slug, data, is_active, sort_order, created_at, updated_at)
  VALUES ('sample-faq-1', 'faqs', NULL, '{"id":"sample-faq-1","question":"Do I pay to place an order?","answer":"No. Placing an order on our website is free. After you order, our team calls you to confirm the details and arrange payment with you.","category":"Ordering","sortOrder":1,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:00.000Z","updatedAt":"2026-09-17T08:00:00.000Z"}', 1, 1, '2026-09-17T08:00:00.000Z', '2026-09-17T08:00:00.000Z')
