    is_active = excluded.is_active, sort_order = excluded.sort_order, updated_at = excluded.updated_at
  WHERE records.collection = 'faqs' AND json_extract(records.data, '$.sample') = 1;
INSERT INTO records (id, collection, slug, data, is_active, sort_order, created_at, updated_at)
  VALUES ('sample-faq-2', 'faqs', NULL, '{"id":"sample-faq-2","question":"How long does installation take?","answer":"Most home systems are installed and tested in one day. Larger systems with many panels can take two to three days. Your engineer confirms the timeline with you before the visit.","category":"Installation","sortOrder":2,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:01.000Z","updatedAt":"2026-09-17T08:00:01.000Z"}', 1, 2, '2026-09-17T08:00:01.000Z', '2026-09-17T08:00:01.000Z')
