  WHERE records.collection = 'faqs' AND json_extract(records.data, '$.sample') = 1;
INSERT INTO records (id, collection, slug, data, is_active, sort_order, created_at, updated_at)
  VALUES ('sample-faq-3', 'faqs', NULL, '{"id":"sample-faq-3","question":"Can I buy a single battery or inverter?","answer":"Yes. Inverters, batteries and solar panels are sold individually on the Products page. Add what you need to your cart and order it the same way as a package.","category":"Products","sortOrder":3,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:02.000Z","updatedAt":"2026-09-17T08:00:02.000Z"}', 1, 3, '2026-09-17T08:00:02.000Z', '2026-09-17T08:00:02.000Z')
