INSERT INTO records (id, collection, slug, data, is_active, sort_order, created_at, updated_at)
  VALUES ('sample-faq-4', 'faqs', NULL, '{"id":"sample-faq-4","question":"What''s the difference between tubular and lithium batteries?","answer":"Tubular batteries cost less up front but are heavier, need a ventilated space and regular water top-ups.\nLithium batteries cost more but are lighter, need no maintenance, charge faster and last for many more charge cycles.\nEvery product page lists the battery''s full specs.","category":"Products","sortOrder":4,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:03.000Z","updatedAt":"2026-09-17T08:00:03.000Z"}', 1, 4, '2026-09-17T08:00:03.000Z', '2026-09-17T08:00:03.000Z')
