INSERT INTO records (id, collection, slug, data, is_active, sort_order, created_at, updated_at)
  VALUES ('sample-faq-7', 'faqs', NULL, '{"id":"sample-faq-7","question":"Can I add solar panels later?","answer":"Yes. Many customers start with an inverter and batteries and add panels later. Our packages come with and without solar, so tell us your plans when we call and we''ll recommend an inverter that can take panels later.","category":"Products","sortOrder":7,"isActive":true,"sample":true,"createdAt":"2026-09-17T08:00:06.000Z","updatedAt":"2026-09-17T08:00:06.000Z"}', 1, 7, '2026-09-17T08:00:06.000Z', '2026-09-17T08:00:06.000Z')
